(() => {
  'use strict';
  const map = document.getElementById('school-map');
  if (!map) return;
  const get = id => document.getElementById(id);
  const motion = matchMedia('(prefers-reduced-motion: reduce)');
  const NS = 'http://www.w3.org/2000/svg';
  const WIDTH = 820, HEIGHT = 560;
  const schools = [
    {code:'GP', city:'Évora', name:'Escola Secundária Gabriel Pereira', point:[-7.902909336,38.5745042], population:53591, color:'#2f6f4e'},
    {code:'MS', city:'Portalegre', name:'Escola Secundária Mouzinho da Silveira', point:[-7.432714403,39.30331558], population:22341, color:'#c4841d'}
  ];
  // A local equirectangular projection, with longitude scaled at 39° N.
  const project = ([lon,lat]) => [lon*Math.cos(39*Math.PI/180), -lat];
  const path = rings => rings.map(ring => ring.map((p,i) => `${i?'L':'M'}${project(p).map(n=>n.toFixed(5)).join(',')}`).join(' ')+'Z').join(' ');
  const element = (tag, attrs, parent) => {
    const node = document.createElementNS(NS,tag);
    Object.entries(attrs).forEach(([k,v])=>node.setAttribute(k,v));
    if(parent) parent.append(node);
    return node;
  };
  const title = element('title',{},map);
  title.textContent = 'From western Europe to Portugal, Évora and Portalegre: the two schools behind the study';
  const defs = element('defs',{},map);
  const clip = element('clipPath',{id:'geo-clip'},defs);
  element('rect',{width:WIDTH,height:HEIGHT,rx:12},clip);
  const scene = element('g',{'clip-path':'url(#geo-clip)'},map);
  element('rect',{width:WIDTH,height:HEIGHT,fill:'#e9f0f1'},scene);
  const land = element('g',{},scene);
  SCHOOL_GEOGRAPHY.land.forEach(country=>element('path',{
    d:path(country.rings),class:country.name==='Portugal'?'geo-country geo-portugal':'geo-country',
    'vector-effect':'non-scaling-stroke'
  },land));
  const municipalities = SCHOOL_GEOGRAPHY.municipalities.map((area,i)=>element('path',{
    d:path(area.rings),class:'geo-municipality','data-city':area.name,
    fill:schools.find(s=>s.city===area.name).color,'vector-effect':'non-scaling-stroke'
  },land));
  const labels = [
    ['PORTUGAL',[-8.55,40.4]], ['SPAIN',[-3.7,40.3]], ['FRANCE',[2.6,46.4]],
    ['ATLANTIC OCEAN',[-12,39.2]]
  ].map(([text,point])=>{
    const node = element('text',{'text-anchor':'middle',class:'geo-place-label'},scene);
    node.textContent=text; return {node,point,text};
  });
  const pins = schools.map((school,index)=>{
    const group = element('g',{'role':'button','tabindex':'0','aria-label':`Zoom to ${school.name}, ${school.city}`,class:'geo-pin'},scene);
    const pinTitle=element('title',{},group);pinTitle.textContent=`${school.name} · ${school.city}`;
    element('circle',{r:21,fill:'transparent'},group);
    element('circle',{r:16,fill:school.color,'fill-opacity':'.12',class:'geo-pin-halo'},group);
    element('circle',{r:6,fill:school.color,stroke:'#fffdf8','stroke-width':2},group);
    const label=element('text',{x:14,y:4,class:'geo-pin-label'},group);label.textContent=school.city;
    group.addEventListener('click',()=>choose(index+2));
    group.addEventListener('keydown',event=>{
      if(event.key==='Enter'||event.key===' '){event.preventDefault();choose(index+2);}
    });
    return {group,school};
  });
  const fit = bounds => {
    const [west,south,east,north]=bounds;
    const a=project([west,north]),b=project([east,south]);
    return {x:(a[0]+b[0])/2,y:(a[1]+b[1])/2,k:Math.min((WIDTH-110)/(b[0]-a[0]),(HEIGHT-100)/(b[1]-a[1]))};
  };
  const municipalBounds = city => {
    const points=SCHOOL_GEOGRAPHY.municipalities.find(a=>a.name===city).rings.flat();
    return [Math.min(...points.map(p=>p[0]))-.1,Math.min(...points.map(p=>p[1]))-.08,
      Math.max(...points.map(p=>p[0]))+.1,Math.max(...points.map(p=>p[1]))+.08];
  };
  const frames = [
    {view:fit([-15,32,12,53]),title:'Portugal',step:'01 / FIND THE COUNTRY',caption:'WESTERN EUROPE',description:'Our story begins in two secondary schools in Portugal’s Alentejo region. Follow the journey from the country to each school community.'},
    {view:fit([-10.05,36.65,-5.8,42.4]),title:'Portugal',step:'01 / FIND THE COUNTRY',caption:'MAINLAND PORTUGAL',description:'Both schools are in the Alentejo region, inland from the Atlantic coast. They are two local communities, not a representative sample of all Portugal.'},
    {view:fit(municipalBounds('Évora')),title:'Évora',step:'02 / MEET GABRIEL PEREIRA',caption:'ÉVORA MUNICIPALITY · SCHOOL GP',description:'Gabriel Pereira is in Évora. The shaded outline is the municipality; the dot marks the school’s published location.',school:schools[0]},
    {view:fit(municipalBounds('Portalegre')),title:'Portalegre',step:'03 / MEET MOUZINHO DA SILVEIRA',caption:'PORTALEGRE MUNICIPALITY · SCHOOL MS',description:'Mouzinho da Silveira is in Portalegre, north-east of Évora. A second setting for the same questions about opportunity and achievement.',school:schools[1]},
    {view:fit([-8.7,38.15,-6.95,39.65]),title:'Both schools',step:'04 / THE STORY STARTS HERE',caption:'ALENTEJO · BOTH SCHOOL LOCATIONS',description:'395 mathematics and 649 Portuguese course records bring these two schools into one story. Some students appear in both subjects; this is not a count of unique students.'}
  ];
  let camera={...frames[0].view}, stage=0, raf=0, timers=[], started=false, generation=0;
  const paint=()=>{
    const {x,y,k}=camera;
    land.setAttribute('transform',`translate(${WIDTH/2-k*x},${HEIGHT/2-k*y}) scale(${k})`);
    const screen=point=>{const p=project(point);return [WIDTH/2+(p[0]-x)*k,HEIGHT/2+(p[1]-y)*k];};
    pins.forEach(({group,school})=>{const [px,py]=screen(school.point);group.setAttribute('transform',`translate(${px},${py})`);});
    labels.forEach(({node,point,text})=>{
      const [px,py]=screen(point);node.setAttribute('x',px);node.setAttribute('y',py);
      node.style.opacity=(stage<2&&(text!=='ATLANTIC OCEAN'||stage<2))?'1':'0';
    });
  };
  const stop=()=>{generation++;timers.forEach(clearTimeout);timers=[];cancelAnimationFrame(raf);get('geo-replay').textContent='Replay journey ↻';};
  function go(index, animate=true) {
    cancelAnimationFrame(raf);stage=index;
    const frame=frames[index],school=frame.school;
    get('geo-step').textContent=frame.step;get('geo-title').textContent=frame.title;
    get('geo-description').textContent=frame.description;get('geo-map-caption').textContent=frame.caption;
    get('geo-pop').innerHTML=school?`<strong>${school.population.toLocaleString('en-US')}</strong><span>municipal residents · 2021</span>`:index===4?'<strong>2</strong><span>schools · 1,044 course records</span>':'<strong>2</strong><span>schools in the study</span>';
    get('geo-school').innerHTML=school?`<span class="geo-school-code" style="background:${school.color}">${school.code}</span> ${school.name}`:'Gabriel Pereira · Évora<br>Mouzinho da Silveira · Portalegre';
    get('geo-footnote').textContent=school?'Population: INE 2021, as published by DGAL. The municipal population is context, not school enrollment or the historical study cohort.':'School dots use published GPS coordinates. The map is geographic context, not a map of students’ homes.';
    get('geo-status').textContent=index===4?'Explore a place, or continue to the evidence below.':`${school?school.city:'Portugal'} · ${index?index:1} of 4`;
    document.querySelectorAll('[data-geo]').forEach(button=>button.setAttribute('aria-pressed',String(+button.dataset.geo===index)));
    municipalities.forEach(node=>node.style.opacity=index>=2?(school&&node.dataset.city!==school.city?'.06':'.22'):'0');
    const from={...camera}, target=frame.view;
    if(!animate||motion.matches){camera={...target};paint();return;}
    const start=performance.now();
    const tick=now=>{
      const t=Math.min(1,(now-start)/1600),ease=t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2;
      camera={x:from.x+(target.x-from.x)*ease,y:from.y+(target.y-from.y)*ease,k:Math.exp(Math.log(from.k)+(Math.log(target.k)-Math.log(from.k))*ease)};
      paint();if(t<1)raf=requestAnimationFrame(tick);
    };
    raf=requestAnimationFrame(tick);
  }
  function choose(index){stop();started=true;go(index);}
  function play(){
    stop();started=true;
    if(motion.matches){go(4,false);return;}
    go(0,false);get('geo-replay').textContent='Pause journey Ⅱ';
    const token=generation;
    [[450,1],[3200,2],[6900,3],[10600,4]].forEach(([delay,index])=>timers.push(setTimeout(()=>{
      if(token!==generation)return;go(index);if(index===4)get('geo-replay').textContent='Replay journey ↻';
    },delay)));
  }
  get('geo-replay').addEventListener('click',()=>{if(timers.length&&stage<4){stop();get('geo-status').textContent='Journey paused. Choose a place or replay.';}else play();});
  document.querySelectorAll('[data-geo]').forEach(button=>button.addEventListener('click',()=>choose(+button.dataset.geo)));
  document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
  motion.addEventListener('change',()=>{stop();go(4,false);});
  paint();
  const visibility=new IntersectionObserver(entries=>{
    entries.forEach(entry=>{
      if(entry.isIntersecting&&!started)play();
      else if(!entry.isIntersecting&&started)stop();
    });
  },{threshold:.25});
  visibility.observe(get('school-geography'));

  // Reveal each visualization as it enters view; all content stays visible without JS.
  if(!motion.matches){
    const reveal=new IntersectionObserver(entries=>entries.forEach(entry=>{
      if(entry.isIntersecting){entry.target.classList.add('is-visible');reveal.unobserve(entry.target);}
    }),{threshold:.06,rootMargin:'0px 0px -20px 0px'});
    document.querySelectorAll('.story-section > .eyebrow,.story-section > h2,.story-section > .section-summary,.story .card,.stat-band').forEach((node,i)=>{
      node.classList.add('story-reveal');node.style.setProperty('--reveal-delay',`${Math.min(i%3,2)*70}ms`);reveal.observe(node);
    });
  }
})();
